    c: "class Temperature {\n  final double celsius;\n  Temperature(this.celsius);\n  Temperature.freezing() : celsius = 0;\n  factory Temperature.fromFahrenheit(double f) => Temperature((f - 32) * 5 / 9);\n}\n\nvoid main() {\n  print(Temperature(21).celsius);\n  print(Temperature.freezing().celsius);\n  print(Temperature.fromFahrenheit(212).celsius);\n}",
