    c: "import 'package:flutter/material.dart';\n\nclass PillButton extends StatelessWidget {\n  final String label;\n  final VoidCallback? onPressed;\n  const PillButton({super.key, required this.label, this.onPressed});\n  @override\n  Widget build(BuildContext context) => FilledButton(onPressed: onPressed, child: Text(label));\n}\n\nvoid main() {\n  runApp(MaterialApp(\n    home: Scaffold(body: Column(children: [\n      PillButton(label: 'Buy', onPressed: () => print('buy')),\n      const PillButton(label: 'Sold out'),\n    ])),\n  ));\n}",
