    c: "bool hasDigit(String s) => '0123456789'.split('').any((d) => s.contains(d));\n\nString? validatePassword(String? v) {\n  final value = v?.trim() ?? '';\n  if (value.length < 8) return 'At least 8 characters';\n  if (!hasDigit(value)) return 'Include a number';\n  return null;\n}\n\nvoid main() {\n  print(validatePassword('short'));\n  print(validatePassword('longpassword'));\n  print(validatePassword('longpass1'));\n}",
