    c: "import 'package:flutter/material.dart';\n\nclass LoginFields extends StatefulWidget {\n  const LoginFields({super.key});\n  @override\n  State<LoginFields> createState() => _LoginFieldsState();\n}\n\nclass _LoginFieldsState extends State<LoginFields> {\n  final passwordFocus = FocusNode();\n  @override\n  void dispose() {\n    passwordFocus.dispose();\n    super.dispose();\n  }\n  @override\n  Widget build(BuildContext context) => Column(children: [\n        TextField(textInputAction: TextInputAction.next, onSubmitted: (_) => passwordFocus.requestFocus()),\n        TextField(focusNode: passwordFocus, obscureText: true),\n      ]);\n}\n\nvoid main() {\n  runApp(const MaterialApp(home: Scaffold(body: LoginFields())));\n}",
